    required int uploadOffset,
    required Stream<List<int>> body,
    CancelToken? cancelToken,
  }) async {
    final response = await transfer<dynamic>(
      'PUT',
      '/v1/media/uploads/${Uri.encodeComponent(id)}',
      body: body,
      headers: {
        "Upload-Offset": uploadOffset,
        'Content-Type': 'application/octet-stream',
      },
      cancelToken: cancelToken,
    );
    return TrainingChunkResponseDto.fromJson(
      Map<String, dynamic>.from(response.data as Map),
    );
  }

  Future<TrainingMetadataResponseDto> trainingMetadata({
    required String id,
    String? variant,
  }) async {
    final value = await request(
      'GET',
      '/v1/media/${Uri.encodeComponent(id)}/metadata',
      query: {"variant": ?variant},
    );
    return TrainingMetadataResponseDto.fromJson(
      Map<String, dynamic>.from(value as Map),
    );
  }

  Future<ResponseBody> trainingMedia({
    required String id,
    String? variant,
    String? range,
    String? ifRange,
    CancelToken? cancelToken,
  }) async {
    final response = await transfer<ResponseBody>(
      'GET',
      '/v1/media/${Uri.encodeComponent(id)}',
      responseType: ResponseType.stream,
      headers: {"Range": ?range, "If-Range": ?ifRange},
      cancelToken: cancelToken,
    );
    return response.data!;
  }

  Future<ReportingOverviewResponseDto> reportingOverview() async {
    final value = await request('GET', '/v1/reports/overview', query: {});
    return ReportingOverviewResponseDto.fromJson(
      Map<String, dynamic>.from(value as Map),
    );
  }

  Future<String> reportingExport({
    required String store,
    required String organizationId,
    String? after,
  }) async {
    final value = await request(
      'GET',
      '/v1/reports/stores/${Uri.encodeComponent(store)}/sales.csv',
      query: {"organizationId": organizationId, "after": ?after},
    );
    return value as String;
  }
}
